    function getUrlPlayerPageParameter() {
      uri = window.location.search.substring(1);
      params = new URLSearchParams(uri);
      cardNumber = params.get("cardNumber");

      if (
        cardNumber == "undefined" ||
        cardNumber == "" ||
        cardNumber == null ||
        cardNumber == undefined
      ) {
        window.location.href =
          "/Campionati-tornei-e-classifiche/Classifiche/Ricerca-Giocatore";
        return false;
      }

      var lenstr = cardNumber.length;
      var res = cardNumber.substring(lenstr - 1, lenstr);
      if (res == "#") {
        var cardNumber = cardNumber.substring(0, lenstr - 1);
      }
      return cardNumber;
    }

    function getUrlParameter() {
      uri = window.location.search.substring(1);
      params = new URLSearchParams(uri);
      appLogin = params.get("appLogin");

      if (
        appLogin == "undefined" ||
        appLogin == "" ||
        appLogin == null ||
        appLogin == undefined
      ) {
        return "";
      }

      return appLogin;
    }

